package com.apismith.instagram.transcriptapi;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

import java.io.IOException;
import java.math.BigDecimal;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.atomic.AtomicInteger;

import static org.junit.jupiter.api.Assertions.*;

class TranscriptClientTest {
    private static final String URL="https://www.instagram.com/reel/AbC_12/";
    private static final String GOOD_ITEM="[{\"url\":\"https://www.instagram.com/reel/AbC_12/\",\"errMsg\":\"\",\"text\":\"hello\",\"segments\":[{\"start\":0.1,\"end\":1.2,\"text\":\"hello\"}],\"pk\":\"00123\",\"duration\":12.345,\"futureActorField\":{\"x\":1}}]";
    private static TranscriptClient client(TestTransport t, Journal j, boolean require, BigDecimal cap) {
        return new TranscriptClient(ClientConfig.builder().token("synthetic-token").transport(t).journal(j).requireChargeCap(require).maxTotalChargeUsd(cap).pollInterval(java.time.Duration.ZERO).sleeper(d -> {}).build());
    }
    private static TranscriptClient client(TestTransport t) { return client(t,new InMemoryJournal(),false,null); }

    @Test void singleSuccessPreservesTextSegmentsAndRawTypes() { var t=TestTransport.successful(GOOD_ITEM);var r=client(t).getTranscript(URL);assertEquals(Status.SUCCESS,r.status());assertEquals("hello",r.text());assertEquals(1,r.segments().size());assertEquals("00123",r.rawItems().get(0).path("pk").asText());assertEquals(12.345,r.rawItems().get(0).path("duration").asDouble(),0.0001);assertEquals(1,r.rawItems().get(0).path("futureActorField").path("x").asInt());assertEquals(1,t.posts); }
    @Test void capIsQueryAndRestartOnErrorFalse() {var t=TestTransport.successful(GOOD_ITEM);client(t,new InMemoryJournal(),true,new BigDecimal("0.10")).getTranscript(URL);var c=t.calls.get(0);assertEquals("0.10",c.query().get("maxTotalChargeUsd"));assertEquals("false",c.query().get("restartOnError"));assertEquals("0.0.50",c.query().get("build"));assertFalse(((ObjectNode)c.body()).has("maxTotalChargeUsd"));}
    @Test void sessionIdIsOnlySentForSingleUrlNotCsvRows() {var single=TestTransport.successful(GOOD_ITEM);new TranscriptClient(ClientConfig.builder().token("x").sessionId("synthetic-session").transport(single).pollInterval(java.time.Duration.ZERO).sleeper(d->{}).build()).getTranscript(URL);assertEquals("synthetic-session",((ObjectNode)single.calls.get(0).body()).path("sessionid").asText());var csv=TestTransport.successful(GOOD_ITEM);new TranscriptClient(ClientConfig.builder().token("x").sessionId("synthetic-session").transport(csv).pollInterval(java.time.Duration.ZERO).sleeper(d->{}).build()).getTranscriptsFromCsv(List.of(new CsvRow("2",URL)));assertFalse(((ObjectNode)csv.calls.get(0).body()).has("sessionid"));}
    @Test void missingRequiredCapBlocksBeforePost() {var t=TestTransport.successful(GOOD_ITEM);assertThrows(ConfigurationException.class,()->client(t,new InMemoryJournal(),true,null).getTranscript(URL));assertEquals(0,t.posts);}
    @Test void journalIntentFailureBlocksPost() {Journal j=new TestJournal(1);var t=TestTransport.successful(GOOD_ITEM);var e=assertThrows(TransportException.class,()->client(t,j,false,null).getTranscript(URL));assertEquals("journal_intent",e.stage());assertEquals(0,t.posts);}
    @Test void journalCreatedImmediatelyContainsIds() {var j=new InMemoryJournal();var t=TestTransport.successful(GOOD_ITEM);client(t,j,false,null).getTranscript(URL);var records=j.readAll();assertEquals("intent",records.get(0).stage());assertEquals("run_created",records.get(1).stage());assertEquals("R1",records.get(1).runId());assertEquals("D1",records.get(1).datasetId());assertFalse(records.get(1).restartOnError());}
    @Test void status429NeverRetriesPost() {var t=new TestTransport().reply(429,"busy");var e=assertThrows(CreationUnknownException.class,()->client(t).getTranscript(URL));assertEquals("creation_unknown",e.stage());assertEquals(1,t.posts);}
    @Test void definitiveCreateRejectionIsJournaledWithoutRetry() {var j=new InMemoryJournal();var t=new TestTransport().reply(400,"invalid");var e=assertThrows(TransportException.class,()->client(t,j,false,null).getTranscript(URL));assertEquals("run_create_rejected",e.stage());assertEquals(1,t.posts);assertEquals("intent",j.readAll().get(0).stage());assertEquals("create_failed",j.readAll().get(1).stage());}
    @Test void status500NeverRetriesPost() {var t=new TestTransport().reply(500,"server");assertThrows(CreationUnknownException.class,()->client(t).getTranscript(URL));assertEquals(1,t.posts);}
    @Test void getRetries429AndHonorsRetryAfterWithoutRecreatingRun() {var sleeps=new java.util.ArrayList<java.time.Duration>();var t=new TestTransport().reply(201,"{\"data\":{\"id\":\"R1\",\"defaultDatasetId\":\"D1\",\"status\":\"RUNNING\"}}").reply(429,"busy",Map.of("retry-after",List.of("2"))).reply(200,"{\"data\":{\"id\":\"R1\",\"defaultDatasetId\":\"D1\",\"status\":\"SUCCEEDED\",\"buildNumber\":\"0.0.50\",\"buildId\":\"aJLRmMdQapLQRT4sJ\"}}").reply(200,GOOD_ITEM);var c=new TranscriptClient(ClientConfig.builder().token("x").transport(t).pollInterval(java.time.Duration.ZERO).sleeper(sleeps::add).build());assertEquals(Status.SUCCESS,c.getTranscript(URL).status());assertEquals(1,t.posts);assertEquals(2,t.calls.stream().filter(x->x.path().startsWith("/actor-runs/")).count());assertEquals(List.of(java.time.Duration.ofSeconds(2)),sleeps);}
    @Test void getRetriesTransportFailureButCreatePostRemainsSingleShot() {var t=new TestTransport().reply(201,"{\"data\":{\"id\":\"R1\",\"defaultDatasetId\":\"D1\",\"status\":\"RUNNING\"}}").fail(new IOException("temporary GET failure")).reply(200,"{\"data\":{\"id\":\"R1\",\"defaultDatasetId\":\"D1\",\"status\":\"SUCCEEDED\",\"buildNumber\":\"0.0.50\",\"buildId\":\"aJLRmMdQapLQRT4sJ\"}}").reply(200,GOOD_ITEM);var c=new TranscriptClient(ClientConfig.builder().token("x").transport(t).pollInterval(java.time.Duration.ZERO).sleeper(d->{}).build());assertEquals(Status.SUCCESS,c.getTranscript(URL).status());assertEquals(1,t.posts);assertEquals(2,t.calls.stream().filter(x->x.path().startsWith("/actor-runs/")).count());}
    @Test void postTimeoutNeverRetriesAndRecordsUnknown() {var j=new InMemoryJournal();var t=new TestTransport().fail(new IOException("timeout"));assertThrows(CreationUnknownException.class,()->client(t,j,false,null).getTranscript(URL));assertEquals(1,t.posts);assertEquals("creation_unknown",j.readAll().get(1).stage());}
    @ParameterizedTest @ValueSource(ints={307,308}) void redirectsNeverReplayPost(int code) {var t=new TestTransport().reply(code,"redirect");assertThrows(CreationUnknownException.class,()->client(t).getTranscript(URL));assertEquals(1,t.posts);}
    @Test void successfulPostThenRunGetBuildMismatchDoesNotReadDataset() {var t=new TestTransport().reply(201,"{\"data\":{\"id\":\"R1\",\"defaultDatasetId\":\"D1\",\"status\":\"RUNNING\"}}").reply(200,"{\"data\":{\"id\":\"R1\",\"defaultDatasetId\":\"D1\",\"status\":\"SUCCEEDED\",\"buildNumber\":\"0.0.51\",\"buildId\":\"aJLRmMdQapLQRT4sJ\"}}");var r=client(t).getTranscript(URL);assertEquals(Status.TRANSPORT_ERROR,r.status());assertEquals(BuildVerification.MISMATCH,r.buildVerification());assertEquals(0,t.calls.stream().filter(c->c.path().startsWith("/datasets/")).count());assertEquals(1,t.posts);}
    @Test void buildIdMismatchDoesNotReadDataset() {var t=new TestTransport().reply(201,"{\"data\":{\"id\":\"R1\",\"defaultDatasetId\":\"D1\",\"status\":\"RUNNING\"}}").reply(200,"{\"data\":{\"id\":\"R1\",\"defaultDatasetId\":\"D1\",\"status\":\"SUCCEEDED\",\"buildNumber\":\"0.0.50\",\"buildId\":\"other\"}}");var r=client(t).getTranscript(URL);assertEquals(BuildVerification.MISMATCH,r.buildVerification());assertEquals(0,t.calls.stream().filter(c->c.path().startsWith("/datasets/")).count());}
    @Test void fullDatasetPageIsIncompleteAndConservative() {StringBuilder b=new StringBuilder("[");for(int i=0;i<2;i++){if(i>0)b.append(',');b.append("{\"url\":\"https://www.instagram.com/reel/x\",\"text\":\"ok\"}");}b.append(']');var t=new TestTransport().reply(201,"{\"data\":{\"id\":\"R1\",\"defaultDatasetId\":\"D1\",\"status\":\"RUNNING\"}}").reply(200,"{\"data\":{\"id\":\"R1\",\"defaultDatasetId\":\"D1\",\"status\":\"SUCCEEDED\",\"buildNumber\":\"0.0.50\",\"buildId\":\"aJLRmMdQapLQRT4sJ\"}}").reply(200,b.toString());var c=new TranscriptClient(ClientConfig.builder().token("x").transport(t).datasetPageLimit(2).pollInterval(java.time.Duration.ZERO).sleeper(d->{}).build());var r=c.getTranscript(URL);assertFalse(r.datasetComplete());assertEquals(Status.UNKNOWN,r.status());}
    @Test void emptyDatasetGetsTwoSameDatasetConfirmationsBeforeEmptyClassification() {var t=TestTransport.successful("[]").reply(200,"[]").reply(200,"[]");var r=client(t).getTranscript(URL);assertEquals(Status.EMPTY,r.status());assertEquals(3,t.calls.stream().filter(c->c.path().startsWith("/datasets/")).count());}
    @Test void datasetConfirmationStopsWhenItemsBecomeVisible() {var t=TestTransport.successful("[]").reply(200,GOOD_ITEM);var r=client(t).getTranscript(URL);assertEquals(Status.SUCCESS,r.status());assertEquals(2,t.calls.stream().filter(c->c.path().startsWith("/datasets/")).count());}
    @Test void runFailureReturnsRunFailed() {var t=new TestTransport().reply(201,"{\"data\":{\"id\":\"R1\",\"defaultDatasetId\":\"D1\",\"status\":\"RUNNING\"}}").reply(200,"{\"data\":{\"id\":\"R1\",\"defaultDatasetId\":\"D1\",\"status\":\"FAILED\",\"buildNumber\":\"0.0.50\",\"buildId\":\"aJLRmMdQapLQRT4sJ\"}}");assertEquals(Status.RUN_FAILED,client(t).getTranscript(URL).status());}
    @ParameterizedTest @ValueSource(strings={"null","\"\""}) void missingOrEmptyTextIsNoTranscript(String value) {var t=TestTransport.successful("[{\"url\":\"https://www.instagram.com/reel/AbC_12/\",\"text\":"+value+"}]");assertEquals(Status.NO_TRANSCRIPT,client(t).getTranscript(URL).status());}
    @ParameterizedTest @ValueSource(strings={"7","true","{}"}) void nonStringTextIsUnknown(String value) {var t=TestTransport.successful("[{\"url\":\"https://www.instagram.com/reel/AbC_12/\",\"text\":"+value+"}]");assertEquals(Status.UNKNOWN,client(t).getTranscript(URL).status());}
    @Test void nonemptyErrMsgIsActorError() {var t=TestTransport.successful("[{\"url\":\"https://www.instagram.com/reel/AbC_12/\",\"errMsg\":\"blocked\"}]");assertEquals(Status.ACTOR_ERROR,client(t).getTranscript(URL).status());}
    @ParameterizedTest @ValueSource(strings={"\"\"","\"   \"","null"}) void blankOrNullErrMsgDoesNotOverrideTranscript(String err) {var t=TestTransport.successful("[{\"url\":\"https://www.instagram.com/reel/AbC_12/\",\"errMsg\":"+err+",\"text\":\"ok\"}]");assertEquals(Status.SUCCESS,client(t).getTranscript(URL).status());}
    @ParameterizedTest @ValueSource(strings={"7","true","{}"}) void nonStringErrMsgIsUnknown(String err) {var t=TestTransport.successful("[{\"url\":\"https://www.instagram.com/reel/AbC_12/\",\"errMsg\":"+err+",\"text\":\"ok\"}]");assertEquals(Status.UNKNOWN,client(t).getTranscript(URL).status());}
    @Test void urlMismatchIsNotAttributed() {var t=TestTransport.successful("[{\"url\":\"https://www.instagram.com/reel/other/\",\"text\":\"wrong\"}]");var r=client(t).getTranscript(URL);assertEquals(AttributionVerification.MISMATCH,r.attributionVerification());assertEquals(Status.UNKNOWN,r.status());}
    @Test void missingOutputUrlIsUnknownAttribution() {var t=TestTransport.successful("[{\"text\":\"ok\"}]");assertEquals(AttributionVerification.UNKNOWN,client(t).getTranscript(URL).attributionVerification());}
    @Test void bulkMapsByUrlNotDatasetOrder() {var t=TestTransport.successful("[{\"url\":\"https://www.instagram.com/reel/b/\",\"text\":\"B\"},{\"url\":\"https://www.instagram.com/reel/a/\",\"text\":\"A\"}]");var r=client(t).getTranscripts(List.of("https://www.instagram.com/reel/a/","https://www.instagram.com/reel/b/"));assertEquals(BulkStatus.ALL_SUCCESS,r.status());assertEquals("A",r.results().get(0).text());assertEquals("B",r.results().get(1).text());}
    @Test void bulkPartialSuccessCountsKnownActorFailure() {var t=TestTransport.successful("[{\"url\":\"https://www.instagram.com/reel/a/\",\"text\":\"A\"},{\"url\":\"https://www.instagram.com/reel/b/\",\"errMsg\":\"blocked\"}]");var r=client(t).getTranscripts(List.of("https://www.instagram.com/reel/a/","https://www.instagram.com/reel/b/"));assertEquals(BulkStatus.PARTIAL_SUCCESS,r.status());assertEquals(1,r.counts().get(BulkItemStatus.SUCCESS_TRANSCRIPT));assertEquals(1,r.counts().get(BulkItemStatus.ACTOR_ERROR));}
    @Test void bulkAllKnownFailuresIsAllFailed() {var t=TestTransport.successful("[{\"url\":\"https://www.instagram.com/reel/a/\",\"errMsg\":\"blocked\"}]");var r=client(t).getTranscripts(List.of("https://www.instagram.com/reel/a/"));assertEquals(BulkStatus.ALL_FAILED,r.status());assertEquals(BulkItemStatus.ACTOR_ERROR,r.results().get(0).status());}
    @Test void bulkMissingItemInCompleteDatasetIsMissingResult() {var t=TestTransport.successful("[]").reply(200,"[]").reply(200,"[]");var r=client(t).getTranscripts(List.of("https://www.instagram.com/reel/a/"));assertTrue(r.datasetComplete());assertEquals(BulkItemStatus.MISSING_RESULT,r.results().get(0).status());assertEquals(BulkStatus.ALL_FAILED,r.status());}
    @Test void bulkMissingItemInIncompleteDatasetRemainsUnknown() {var t=TestTransport.successful("[{\"url\":\"https://www.instagram.com/reel/a/\",\"text\":\"A\"}]");var c=new TranscriptClient(ClientConfig.builder().token("x").transport(t).datasetPageLimit(1).pollInterval(java.time.Duration.ZERO).sleeper(d->{}).build());var r=c.getTranscripts(List.of("https://www.instagram.com/reel/a/","https://www.instagram.com/reel/b/"));assertFalse(r.datasetComplete());assertEquals(BulkItemStatus.UNKNOWN,r.results().get(1).status());assertEquals(BulkStatus.UNKNOWN,r.status());}
    @Test void bulkExtraItemIsPreservedAndMakesAggregateUnknown() {var t=TestTransport.successful("[{\"url\":\"https://www.instagram.com/reel/a/\",\"text\":\"A\"},{\"url\":\"https://www.instagram.com/reel/extra/\",\"text\":\"extra\"}]");var r=client(t).getTranscripts(List.of("https://www.instagram.com/reel/a/"));assertEquals(BulkStatus.UNKNOWN,r.status());assertEquals(1,r.extras().size());assertEquals("output_url_not_in_input",r.extras().get(0).reason());assertEquals("extra",r.extras().get(0).item().path("text").asText());}
    @Test void bulkShortcodeFallbackOnlyWhenUrlMissing() {var t=TestTransport.successful("[{\"code\":\"a\",\"text\":\"A\"}]");var r=client(t).getTranscripts(List.of("https://www.instagram.com/reel/a/"));assertEquals(BulkItemStatus.SUCCESS_TRANSCRIPT,r.results().get(0).status());}
    @Test void bulkUrlCodeConflictBecomesExtra() {var t=TestTransport.successful("[{\"url\":\"https://www.instagram.com/reel/a/\",\"code\":\"b\",\"text\":\"A\"}]");var r=client(t).getTranscripts(List.of("https://www.instagram.com/reel/a/","https://www.instagram.com/reel/b/"));assertEquals(1,r.extras().size());assertEquals("url_code_conflict",r.extras().get(0).reason());}
    @Test void bulkDuplicateResultsAreNotCollapsed() {var t=TestTransport.successful("[{\"url\":\"https://www.instagram.com/reel/a/\",\"text\":\"A\"},{\"url\":\"https://www.instagram.com/reel/a/\",\"text\":\"A2\"}]");var r=client(t).getTranscripts(List.of("https://www.instagram.com/reel/a/"));assertEquals(BulkItemStatus.DUPLICATE_RESULT,r.results().get(0).status());}
    @Test void bulkRunFailedMakesAllUnknown() {var t=new TestTransport().reply(201,"{\"data\":{\"id\":\"R1\",\"defaultDatasetId\":\"D1\",\"status\":\"RUNNING\"}}").reply(200,"{\"data\":{\"id\":\"R1\",\"defaultDatasetId\":\"D1\",\"status\":\"FAILED\",\"buildNumber\":\"0.0.50\",\"buildId\":\"aJLRmMdQapLQRT4sJ\"}}");var r=client(t).getTranscripts(List.of("https://www.instagram.com/reel/a/"));assertEquals(BulkItemStatus.UNKNOWN,r.results().get(0).status());}
    @Test void profileDoesNotRequireTranscriptAndKeepsOwner() {var t=TestTransport.successful("[{\"ownerUsername\":\"alice\",\"userName\":\"wrong\",\"type\":\"Video\",\"timestamp\":123456,\"pk\":\"0001\"}]");var r=client(t).getProfilePosts("alice");assertEquals(ProfileStatus.SUCCESS,r.status());assertEquals("alice",r.posts().get(0).ownerUsername());assertEquals(123456,r.posts().get(0).timestamp().asInt());}
    @Test void profileDoesNotUseUserNameAsOwner() {var t=TestTransport.successful("[{\"userName\":\"alice\",\"type\":\"Video\"}]");var r=client(t).getProfilePosts(List.of("alice","bob"));assertEquals("unknown",r.posts().get(0).status());}
    @Test void profileOwnerCaseMismatchIsUnknown(){var t=TestTransport.successful("[{\"ownerUsername\":\"Alice\"}]");assertEquals(ProfileStatus.UNKNOWN,client(t).getProfilePosts("alice").status());}
    @Test void profileEmptyIsEmpty() {var t=TestTransport.successful("[]").reply(200,"[]").reply(200,"[]");assertEquals(ProfileStatus.EMPTY,client(t).getProfilePosts("alice").status());}
    @Test void profileOwnerConflictIsUnknown() {var t=TestTransport.successful("[{\"ownerUsername\":\"bob\"}]");assertEquals(ProfileStatus.UNKNOWN,client(t).getProfilePosts("alice").status());}
    @Test void invalidBulkDuplicateRejectedBeforePost() {var t=TestTransport.successful("[]");assertThrows(ConfigurationException.class,()->client(t).getTranscripts(List.of("https://www.instagram.com/reel/a/","https://instagram.com/reel/a/")));assertEquals(0,t.posts);}
    @Test void bulkRejectsDifferentPathAliasesWithSameShortcode(){assertThrows(ConfigurationException.class,()->InputValidators.validateBulkInput(List.of("https://www.instagram.com/reel/a/","https://www.instagram.com/reels/a/")));}
    @Test void invalidProfileUsernameRejectedBeforePost() {var t=TestTransport.successful("[]");assertThrows(ConfigurationException.class,()->client(t).getProfilePosts("@alice"));assertEquals(0,t.posts);}
    @Test void planCsvUsesExactBigDecimal() {var t=TestTransport.successful("[]");var c=client(t,new InMemoryJournal(),true,new BigDecimal("0.10"));var p=c.planCsv(List.of(new CsvRow("2",URL),new CsvRow("3",URL)));assertEquals(new BigDecimal("0.20"),p.estimatedMaximumRunCapsTotalUsd());assertEquals(0,t.posts);}
    @Test void csvJournalFailureStopsLaterRows() {Journal j=new TestJournal(6);var t=TestTransport.successful(GOOD_ITEM);var c=client(t,j,false,null);var r=c.getTranscriptsFromCsv(List.of(new CsvRow("2",URL),new CsvRow("3",URL),new CsvRow("4",URL)));assertTrue(r.stopped());assertEquals(1,t.posts);assertEquals(2,r.processedRows());assertEquals(1,r.unattemptedRows());assertEquals("stopped_unknown",r.status());}
    @Test void csvCreationUnknownStopsLaterRows() {var t=TestTransport.successful(GOOD_ITEM).fail(new IOException("timeout"));var c=client(t);var r=c.getTranscriptsFromCsv(List.of(new CsvRow("2",URL),new CsvRow("3","https://www.instagram.com/reel/b/"),new CsvRow("4","https://www.instagram.com/reel/c/")));assertTrue(r.stopped());assertEquals(2,t.posts);assertEquals(1,r.unattemptedRows());}
    @Test void resumeIsGetOnlyAndValidatesCompleteInputContext() {var j=new InMemoryJournal();JsonNode ctx=JsonSupport.MAPPER.createObjectNode().put("mode","single").set("input",JsonSupport.MAPPER.createObjectNode().put("videoUrl",URL));j.append(new JournalRecord("now","complete","single",ClientConfig.DEFAULT_ACTOR_ID,URL,"R1","apple_yang/instagram-transcripts-scraper","D1","RUNNING","0.0.50",ClientConfig.CONTROLLED_BUILD_ID,"verified",null,false,ctx,null));var t=new TestTransport().reply(200,"{\"data\":{\"id\":\"R1\",\"defaultDatasetId\":\"D1\",\"status\":\"SUCCEEDED\",\"buildNumber\":\"0.0.50\",\"buildId\":\"aJLRmMdQapLQRT4sJ\"}}").reply(200,GOOD_ITEM);assertEquals(Status.SUCCESS,client(t,j,false,null).resumeTranscript("R1").status());assertEquals(0,t.posts);}
    @Test void resumeMissingInputContextFailsBeforeNetwork() {var j=new InMemoryJournal();j.append(new JournalRecord("now","complete","single",ClientConfig.DEFAULT_ACTOR_ID,URL,"R1","actor","D1","SUCCEEDED","0.0.50",ClientConfig.CONTROLLED_BUILD_ID,"verified",null,false,null,null));var t=new TestTransport();assertThrows(ConfigurationException.class,()->client(t,j,false,null).resumeTranscript("R1"));assertTrue(t.calls.isEmpty());}
    @Test void resumeBulkChecksOptionsAndDoesNotPost() {var j=new InMemoryJournal();var input=JsonSupport.MAPPER.createObjectNode();input.putArray("bulkUrls").add("https://www.instagram.com/reel/a/");var ctxNode=JsonSupport.MAPPER.createObjectNode();ctxNode.put("mode","bulk");ctxNode.set("input",input);JsonNode ctx=ctxNode;j.append(new JournalRecord("now","complete","bulk",ClientConfig.DEFAULT_ACTOR_ID,"native_bulk:a","R1","actor","D1","RUNNING","0.0.50",ClientConfig.CONTROLLED_BUILD_ID,"verified",null,false,ctx,null));var t=new TestTransport().reply(200,"{\"data\":{\"id\":\"R1\",\"defaultDatasetId\":\"D1\",\"status\":\"SUCCEEDED\",\"buildNumber\":\"0.0.50\",\"buildId\":\"aJLRmMdQapLQRT4sJ\"}}").reply(200,"[{\"url\":\"https://www.instagram.com/reel/a/\",\"text\":\"a\"}]");assertEquals(BulkStatus.ALL_SUCCESS,client(t,j,false,null).resumeTranscripts("R1",List.of("https://www.instagram.com/reel/a/")).status());assertEquals(0,t.posts);}
    @Test void journalLatestUsesLastMatchingRecord() throws Exception {var path=Files.createTempFile("journal",".jsonl");var j=JsonlFileJournal.open(path);j.append(new JournalRecord("1","intent","single","a","u","R","a","D","RUNNING","0.0.50","id","unknown",null,false,null,null));j.append(new JournalRecord("2","complete","single","a","u","R","a","D","SUCCEEDED","0.0.50","id","verified",null,false,null,null));assertEquals("complete",j.latest("R").orElseThrow().stage());assertEquals(2,j.readAll().size());}
    @Test void outputFilesAreUniqueAndPrivate() throws Exception {var d=Files.createTempDirectory("out");var r=client(TestTransport.successful(GOOD_ITEM)).getTranscript(URL);var a=OutputFiles.writeUnique(d,"test",OutputFiles.singleDocument(r),java.time.Clock.systemUTC());var b=OutputFiles.writeUnique(d,"test",OutputFiles.singleDocument(r),java.time.Clock.systemUTC());assertNotEquals(a,b);assertTrue(Files.exists(a));try{assertEquals(java.util.EnumSet.of(java.nio.file.attribute.PosixFilePermission.OWNER_READ,java.nio.file.attribute.PosixFilePermission.OWNER_WRITE),Files.getPosixFilePermissions(a));}catch(UnsupportedOperationException ignored){}}
    @Test void sanitizerRemovesSecretKeysAndRedactsValues() throws Exception {var d=Files.createTempDirectory("out");var file=OutputFiles.writeUnique(d,"safe",Map.of("token","synthetic","message","Bearer abcdef123456","ordinary","ok"),java.time.Clock.systemUTC());String s=Files.readString(file);assertFalse(s.contains("abcdef123456"));assertFalse(s.contains("\"token\""));assertTrue(s.contains("[REDACTED]"));}
    @ParameterizedTest @ValueSource(strings={"http://www.instagram.com/reel/a/","https://www.instagram.com/reel/a/?x=1","https://www.instagram.com/p/","[https://www.instagram.com/reel/a/](x)","https://evil.example/reel/a/"}) void invalidUrlsRejected(String input) {assertThrows(ConfigurationException.class,()->InputValidators.validateVideoUrl(input));}
    @ParameterizedTest @ValueSource(strings={"alice","a.b","abc_1","lovepegz"}) void validProfileNamesAccepted(String input) {assertEquals(input,InputValidators.validateUsernames(List.of(input)).get(0));}
    @ParameterizedTest @ValueSource(strings={"@alice",".alice","alice.","alice bob","a..b",""}) void invalidProfileNamesRejected(String input) {assertThrows(ConfigurationException.class,()->InputValidators.validateUsernames(List.of(input)));}
}
